// vibespace-mic.cs — the VibeSpace agent's MICROPHONE helper on Windows (lane stream-mic-road; the measured road: lane
// stream-mic-wheel-probe, scripts/probes/stream-mic/win/vs-mic-probe.cs). Built ON the machine by its agent with the in-box C# 5
// compiler (src/mic-model.js winMicBuildPlan — the window helper's way); its text rides the agent's bundle
// (src/mic-helper-source.js, generated by scripts/mic-helper-embed.mjs — never edit that file by hand).
//   facts       every audio endpoint (render + capture, any state) with its id and the default endpoint per flow x role — the
//               machine's state («VB-CABLE absent / installed / turned off») and which microphone is the default
//   render      the viewer's decoded voice — s16le 48 kHz stereo PCM on stdin — into ONE render endpoint, WASAPI shared mode
//               (the engine converts to the endpoint's mix): VS_MIC_DEVICE = the endpoint id («CABLE Input» — every app that
//               picks «CABLE Output» hears it), or VS_MIC_SPEAKERS=1 = the default speaker (the intercom: no virtual
//               microphone yet). Ends when stdin closes. stderr: one JSON line per event (started, stats once a second, end)
//   setdefault  the default CAPTURE endpoint for every role (IPolicyConfig — what every audio switcher calls): VS_MIC_DEVICE
//               = the endpoint id; the 「设为默认麦克风」 / 「改回」 pair
//   loopback    the machine's SOUND for the stream's 「声音」 (lane speaker-passthrough-v1, backlog B-aec9; the measured road: lane
//               stream-audio-probe, scripts/probes/stream-audio/win/vs-audio-probe.cs): WASAPI LOOPBACK of the default speaker
//               (event-driven; AUTOCONVERTPCM → 48 kHz float stereo) → s16le PCM on stdout, while a SILENT render stream stays
//               open on the same endpoint (the keep-alive — without it a quiet machine delivers no packet and the encoder
//               starves: the probe's leg 1b). It reads what the speakers play, never a microphone. Ends when stdin closes (the
//               agent's off) or stdout does. stderr: started, stats once a second (packets, silent, peak), end
// Every name rides the env, never argv. Nothing captured is ever written anywhere but the agent's pipe.
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Text;
using System.Threading;

namespace VibeSpaceMic {

[ComImport, Guid("BCDE0395-E52F-467C-8E3D-C4579291692E")] class MMDeviceEnumeratorCo { }
[ComImport, Guid("A95664D2-9614-4F35-A746-DE8DB63617E6"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
interface IMMDeviceEnumerator {
  [PreserveSig] int EnumAudioEndpoints(int dataFlow, int stateMask, out IMMDeviceCollection devices);
  [PreserveSig] int GetDefaultAudioEndpoint(int dataFlow, int role, out IMMDevice endpoint);
  [PreserveSig] int GetDevice([MarshalAs(UnmanagedType.LPWStr)] string id, out IMMDevice device);
}
[ComImport, Guid("0BD7A1BE-7A1A-44DB-8397-CC5392387B5E"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
interface IMMDeviceCollection {
  [PreserveSig] int GetCount(out int count);
  [PreserveSig] int Item(int index, out IMMDevice device);
}
[ComImport, Guid("D666063F-1587-4E43-81F1-B948E807363F"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
interface IMMDevice {
  [PreserveSig] int Activate(ref Guid iid, int clsCtx, IntPtr activationParams, [MarshalAs(UnmanagedType.IUnknown)] out object iface);
  [PreserveSig] int OpenPropertyStore(int access, out IPropertyStore props);
  [PreserveSig] int GetId([MarshalAs(UnmanagedType.LPWStr)] out string id);
  [PreserveSig] int GetState(out int state);
}
[StructLayout(LayoutKind.Sequential)] struct PROPERTYKEY { public Guid fmtid; public int pid; }
[StructLayout(LayoutKind.Sequential)] struct PROPVARIANT { public ushort vt; public ushort r1, r2, r3; public IntPtr p; public IntPtr p2; }
[ComImport, Guid("886d8eeb-8cf2-4446-8d02-cdba1dbdcf99"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
interface IPropertyStore {
  [PreserveSig] int GetCount(out int count);
  [PreserveSig] int GetAt(int index, out PROPERTYKEY key);
  [PreserveSig] int GetValue(ref PROPERTYKEY key, out PROPVARIANT pv);
}
[ComImport, Guid("1CB9AD4C-DBFA-4c32-B178-C2F568A703B2"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
interface IAudioClient {
  [PreserveSig] int Initialize(int shareMode, int streamFlags, long hnsBufferDuration, long hnsPeriodicity, IntPtr pFormat, IntPtr sessionGuid);
  [PreserveSig] int GetBufferSize(out uint frames);
  [PreserveSig] int GetStreamLatency(out long hns);
  [PreserveSig] int GetCurrentPadding(out uint frames);
  [PreserveSig] int IsFormatSupported(int shareMode, IntPtr pFormat, out IntPtr closest);
  [PreserveSig] int GetMixFormat(out IntPtr format);
  [PreserveSig] int GetDevicePeriod(out long defaultPeriod, out long minimumPeriod);
  [PreserveSig] int Start();
  [PreserveSig] int Stop();
  [PreserveSig] int Reset();
  [PreserveSig] int SetEventHandle(IntPtr handle);
  [PreserveSig] int GetService(ref Guid iid, [MarshalAs(UnmanagedType.IUnknown)] out object service);
}
[ComImport, Guid("C8ADBD64-E71E-48a0-A4DE-185C395CD317"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
interface IAudioCaptureClient {
  [PreserveSig] int GetBuffer(out IntPtr data, out uint frames, out uint flags, out ulong devicePosition, out ulong qpcPosition);
  [PreserveSig] int ReleaseBuffer(uint frames);
  [PreserveSig] int GetNextPacketSize(out uint frames);
}
[ComImport, Guid("F294ACFC-3146-4483-A7BF-ADDCA7C260E2"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
interface IAudioRenderClient {
  [PreserveSig] int GetBuffer(uint frames, out IntPtr data);
  [PreserveSig] int ReleaseBuffer(uint frames, uint flags);
}
// IPolicyConfig (Windows 7+; the vtable every audio switcher uses). Only SetDefaultEndpoint is called — the slots before it
// are placeholders so the vtable lines up.
[ComImport, Guid("870af99c-171d-4f9e-af0d-e63df40c2bc9")] class PolicyConfigClient { }
[ComImport, Guid("f8679f50-850a-41cf-9c72-430f290290c8"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
interface IPolicyConfig {
  [PreserveSig] int GetMixFormat(IntPtr a, IntPtr b);
  [PreserveSig] int GetDeviceFormat(IntPtr a, int b, IntPtr c);
  [PreserveSig] int ResetDeviceFormat(IntPtr a);
  [PreserveSig] int SetDeviceFormat(IntPtr a, IntPtr b, IntPtr c);
  [PreserveSig] int GetProcessingPeriod(IntPtr a, int b, IntPtr c, IntPtr d);
  [PreserveSig] int SetProcessingPeriod(IntPtr a, IntPtr b);
  [PreserveSig] int GetShareMode(IntPtr a, IntPtr b);
  [PreserveSig] int SetShareMode(IntPtr a, IntPtr b);
  [PreserveSig] int GetPropertyValue(IntPtr a, IntPtr b, IntPtr c);
  [PreserveSig] int SetPropertyValue(IntPtr a, IntPtr b, IntPtr c);
  [PreserveSig] int SetDefaultEndpoint([MarshalAs(UnmanagedType.LPWStr)] string deviceId, int role);
}
static class Native {
  [DllImport("ole32.dll")] public static extern int PropVariantClear(ref PROPVARIANT pv);
  [DllImport("ole32.dll")] public static extern void CoTaskMemFree(IntPtr p);
}

static class Ep {
  static readonly PROPERTYKEY NameKey = new PROPERTYKEY { fmtid = new Guid("a45c254e-df1c-4efd-8020-67d146a850e0"), pid = 14 }; // PKEY_Device_FriendlyName
  public static IMMDeviceEnumerator En() { return (IMMDeviceEnumerator)new MMDeviceEnumeratorCo(); }
  public static string NameOf(IMMDevice d) {
    string name = ""; IPropertyStore ps; PROPERTYKEY k = NameKey;
    if (d.OpenPropertyStore(0, out ps) == 0) { PROPVARIANT pv; if (ps.GetValue(ref k, out pv) == 0) { if (pv.vt == 31) name = Marshal.PtrToStringUni(pv.p); Native.PropVariantClear(ref pv); } }
    return name;
  }
  public static string IdOf(IMMDevice d) { string id; return d.GetId(out id) == 0 ? id : ""; }
  public static string DefaultId(int flow, int role) { IMMDevice d; return En().GetDefaultAudioEndpoint(flow, role, out d) == 0 ? IdOf(d) : ""; }
  public static void Check(int hr, string what) { if (hr != 0) throw new Exception(what + " failed 0x" + hr.ToString("X8")); }
}

class Program {
  static readonly string[] Roles = { "console", "multimedia", "communications" };
  public static string Q(string s) {
    var b = new StringBuilder("\"");
    foreach (char c in s ?? "") { if (c == '"' || c == '\\') b.Append('\\').Append(c); else if (c < 32 || c > 126) b.Append("\\u").Append(((int)c).ToString("x4")); else b.Append(c); }
    return b.Append('"').ToString();
  }
  static void Ev(string json) { Console.Error.WriteLine(json); Console.Error.Flush(); }

  [MTAThread]
  static int Main(string[] args) {
    string cmd = args.Length > 0 ? args[0] : "";
    try {
      if (cmd == "facts") return Facts();
      if (cmd == "render") return Render();
      if (cmd == "setdefault") return SetDefault();
      if (cmd == "loopback") return Loopback();
      Console.Error.WriteLine("usage: vibespace-mic facts | render | setdefault | loopback (names ride the env: VS_MIC_DEVICE, VS_MIC_SPEAKERS)");
      return 2;
    } catch (Exception e) { Console.WriteLine("{\"ok\":false,\"error\":" + Q(e.Message) + "}"); Ev("{\"ev\":\"error\",\"error\":" + Q(e.Message) + "}"); return 1; }
  }

  static int Facts() {
    var en = Ep.En();
    var sb = new StringBuilder("{\"ok\":true,\"endpoints\":[");
    var defaults = new StringBuilder(); bool first = true;
    for (int flow = 0; flow < 2; flow++) {
      var defs = new string[3]; for (int r = 0; r < 3; r++) defs[r] = Ep.DefaultId(flow, r);
      IMMDeviceCollection col; if (en.EnumAudioEndpoints(flow, 0xF, out col) != 0) continue;
      int n; col.GetCount(out n);
      var nameOfId = new Dictionary<string, string>();
      for (int i = 0; i < n; i++) {
        IMMDevice d; col.Item(i, out d); string id = Ep.IdOf(d); int state; d.GetState(out state); string name = Ep.NameOf(d); nameOfId[id] = name;
        var roles = new List<string>(); for (int r = 0; r < 3; r++) if (defs[r] == id) roles.Add("\"" + Roles[r] + "\"");
        sb.Append(first ? "" : ",").Append("{\"flow\":\"" + (flow == 0 ? "render" : "capture") + "\",\"name\":" + Q(name) + ",\"state\":" + state + ",\"id\":" + Q(id) + ",\"defaultFor\":[" + string.Join(",", roles.ToArray()) + "]}");
        first = false;
      }
      defaults.Append(defaults.Length > 0 ? "," : "").Append("\"" + (flow == 0 ? "render" : "capture") + "\":{");
      for (int r = 0; r < 3; r++) { string nm; nameOfId.TryGetValue(defs[r], out nm); defaults.Append((r > 0 ? "," : "") + "\"" + Roles[r] + "\":{\"name\":" + Q(nm) + ",\"id\":" + Q(defs[r]) + "}"); }
      defaults.Append("}");
    }
    sb.Append("],\"defaults\":{").Append(defaults).Append("}}");
    Console.WriteLine(sb.ToString());
    return 0;
  }

  /// render: stdin s16le 48 kHz stereo → a queue (at most 400 ms: older audio is dropped, never played late) → the endpoint.
  static int Render() {
    string id = Environment.GetEnvironmentVariable("VS_MIC_DEVICE") ?? "";
    bool speakers = Environment.GetEnvironmentVariable("VS_MIC_SPEAKERS") == "1";
    IMMDevice dev;
    if (speakers) Ep.Check(Ep.En().GetDefaultAudioEndpoint(0, 0, out dev), "GetDefaultAudioEndpoint");
    else { if (id == "") throw new Exception("VS_MIC_DEVICE names no endpoint"); Ep.Check(Ep.En().GetDevice(id, out dev), "GetDevice"); }
    string name = Ep.NameOf(dev);
    Guid iid = new Guid("1CB9AD4C-DBFA-4c32-B178-C2F568A703B2"); object o;
    Ep.Check(dev.Activate(ref iid, 23, IntPtr.Zero, out o), "Activate"); var ac = (IAudioClient)o;
    IntPtr fmt = Marshal.AllocHGlobal(18); // WAVE_FORMAT_IEEE_FLOAT 48 kHz stereo, the engine converts (AUTOCONVERTPCM | SRC_DEFAULT_QUALITY)
    Marshal.WriteInt16(fmt, 0, 3); Marshal.WriteInt16(fmt, 2, 2); Marshal.WriteInt32(fmt, 4, 48000); Marshal.WriteInt32(fmt, 8, 48000 * 8);
    Marshal.WriteInt16(fmt, 12, 8); Marshal.WriteInt16(fmt, 14, 32); Marshal.WriteInt16(fmt, 16, 0);
    Ep.Check(ac.Initialize(0, 0x00040000 | unchecked((int)0x80000000) | 0x08000000, 400000, 0, fmt, IntPtr.Zero), "Initialize");
    Marshal.FreeHGlobal(fmt);
    uint bufFrames; ac.GetBufferSize(out bufFrames);
    var ev = new AutoResetEvent(false); Ep.Check(ac.SetEventHandle(ev.SafeWaitHandle.DangerousGetHandle()), "SetEventHandle");
    Guid rcid = new Guid("F294ACFC-3146-4483-A7BF-ADDCA7C260E2"); object ro; Ep.Check(ac.GetService(ref rcid, out ro), "GetService"); var rc = (IAudioRenderClient)ro;

    var queue = new Queue<float>(); object qLock = new object(); bool open = true, started = false; long inBytes = 0, dropped = 0; const int MAXQ = 48000 * 2 * 4 / 10, PRE = 48 * 20 * 2;
    var reader = new Thread(() => {
      var s = Console.OpenStandardInput(); var b = new byte[3840]; var cb = new byte[2]; int carry = 0, n;
      try {
        while ((n = s.Read(b, 0, b.Length)) > 0) {
          inBytes += n;
          lock (qLock) {
            for (int i = 0; i < n; i++) { cb[carry++] = b[i]; if (carry < 2) continue; carry = 0; queue.Enqueue(BitConverter.ToInt16(cb, 0) / 32768f); }
            while (queue.Count > MAXQ) { queue.Dequeue(); dropped++; }
          }
        }
      } catch { }
      open = false;
    });
    reader.IsBackground = true; reader.Start();
    long written = 0, underruns = 0; var t0 = DateTime.UtcNow; int lastSec = 0;
    Ep.Check(ac.Start(), "Start");
    Ev("{\"ev\":\"started\",\"endpoint\":" + Q(name) + ",\"speakers\":" + (speakers ? "true" : "false") + ",\"bufferFrames\":" + bufFrames + "}");
    var buf = new float[bufFrames * 2];
    for (;;) {
      ev.WaitOne(200);
      uint pad; if (ac.GetCurrentPadding(out pad) != 0) break;
      uint want = bufFrames - pad; if (want == 0) continue;
      int got = 0;
      lock (qLock) {
        if (!started && (queue.Count >= PRE || !open)) started = true;
        if (started) while (got < want && queue.Count >= 2) { buf[got * 2] = queue.Dequeue(); buf[got * 2 + 1] = queue.Dequeue(); got++; }
        if (!open && queue.Count < 2 && got == 0) break;
      }
      if (started && got < want && pad == 0) underruns++;
      IntPtr data; if (rc.GetBuffer(want, out data) != 0) continue;
      Array.Clear(buf, got * 2, (int)(want - got) * 2);
      Marshal.Copy(buf, 0, data, (int)want * 2);
      rc.ReleaseBuffer(want, 0); written += want;
      int sec = (int)(DateTime.UtcNow - t0).TotalSeconds;
      if (sec != lastSec) { lastSec = sec; Ev("{\"ev\":\"stats\",\"frames\":" + written + ",\"inBytes\":" + inBytes + ",\"underruns\":" + underruns + ",\"dropped\":" + dropped + "}"); }
    }
    Thread.Sleep(50);
    ac.Stop();
    Ev("{\"ev\":\"end\",\"why\":\"stdin_closed\",\"frames\":" + written + ",\"inBytes\":" + inBytes + "}");
    return 0;
  }

  /// WAVE_FORMAT_IEEE_FLOAT 48 kHz stereo — what AUTOCONVERTPCM gives (the engine converts from the endpoint's mix).
  static IntPtr Float48Stereo() {
    IntPtr fmt = Marshal.AllocHGlobal(18);
    Marshal.WriteInt16(fmt, 0, 3); Marshal.WriteInt16(fmt, 2, 2); Marshal.WriteInt32(fmt, 4, 48000); Marshal.WriteInt32(fmt, 8, 48000 * 8);
    Marshal.WriteInt16(fmt, 12, 8); Marshal.WriteInt16(fmt, 14, 32); Marshal.WriteInt16(fmt, 16, 0);
    return fmt;
  }
  const int AUTOCONVERT = unchecked((int)0x80000000) | 0x08000000; // AUTOCONVERTPCM | SRC_DEFAULT_QUALITY

  /// loopback: the default speaker's mix → s16le 48 kHz stereo on stdout, a silent keep-alive render stream beside it.
  static int Loopback() {
    IMMDevice dev; Ep.Check(Ep.En().GetDefaultAudioEndpoint(0, 0, out dev), "GetDefaultAudioEndpoint");
    string name = Ep.NameOf(dev);
    Guid iid = new Guid("1CB9AD4C-DBFA-4c32-B178-C2F568A703B2"); object o;
    // THE KEEP-ALIVE: our own render stream of silence on the same endpoint (event-driven shared mode, AUDCLNT_BUFFERFLAGS_SILENT)
    Ep.Check(dev.Activate(ref iid, 23, IntPtr.Zero, out o), "Activate keep-alive"); var ka = (IAudioClient)o;
    IntPtr fmt = Float48Stereo();
    Ep.Check(ka.Initialize(0, 0x00040000 | AUTOCONVERT, 400000, 0, fmt, IntPtr.Zero), "Initialize keep-alive");
    uint kaFrames; ka.GetBufferSize(out kaFrames);
    var kaEv = new AutoResetEvent(false); Ep.Check(ka.SetEventHandle(kaEv.SafeWaitHandle.DangerousGetHandle()), "SetEventHandle keep-alive");
    Guid rcid = new Guid("F294ACFC-3146-4483-A7BF-ADDCA7C260E2"); object ro; Ep.Check(ka.GetService(ref rcid, out ro), "GetService keep-alive"); var rc = (IAudioRenderClient)ro;
    IntPtr z; if (rc.GetBuffer(kaFrames, out z) == 0) rc.ReleaseBuffer(kaFrames, 2);
    Ep.Check(ka.Start(), "Start keep-alive");
    bool open = true;
    var keep = new Thread(() => { while (open) { if (!kaEv.WaitOne(200)) continue; uint pad; if (ka.GetCurrentPadding(out pad) != 0) continue; uint want = kaFrames - pad; IntPtr d; if (want > 0 && rc.GetBuffer(want, out d) == 0) rc.ReleaseBuffer(want, 2); } });
    keep.IsBackground = true; keep.Start();
    // THE LOOPBACK: event-driven where the engine signals it (Windows 10+), else polled every 5 ms
    Ep.Check(dev.Activate(ref iid, 23, IntPtr.Zero, out o), "Activate loopback"); var lb = (IAudioClient)o;
    bool eventMode = lb.Initialize(0, 0x00020000 | 0x00040000 | AUTOCONVERT, 1000000, 0, fmt, IntPtr.Zero) == 0;
    if (!eventMode) { Ep.Check(dev.Activate(ref iid, 23, IntPtr.Zero, out o), "Activate loopback#2"); lb = (IAudioClient)o; Ep.Check(lb.Initialize(0, 0x00020000 | AUTOCONVERT, 1000000, 0, fmt, IntPtr.Zero), "Initialize loopback"); }
    Marshal.FreeHGlobal(fmt);
    var ev = new AutoResetEvent(false);
    if (eventMode) Ep.Check(lb.SetEventHandle(ev.SafeWaitHandle.DangerousGetHandle()), "SetEventHandle loopback");
    Guid ccid = new Guid("C8ADBD64-E71E-48a0-A4DE-185C395CD317"); object co; Ep.Check(lb.GetService(ref ccid, out co), "GetService loopback"); var cc = (IAudioCaptureClient)co;
    var stdin = new Thread(() => { try { var s = Console.OpenStandardInput(); var b = new byte[64]; while (s.Read(b, 0, b.Length) > 0) { } } catch { } open = false; });
    stdin.IsBackground = true; stdin.Start();
    var outStream = Console.OpenStandardOutput();
    Ep.Check(lb.Start(), "Start loopback");
    Ev("{\"ev\":\"started\",\"endpoint\":" + Q(name) + ",\"eventMode\":" + (eventMode ? "true" : "false") + "}");
    long packets = 0, frames = 0, silent = 0, outBytes = 0; float peak = 0; var t0 = DateTime.UtcNow; int lastSec = 0;
    var fl = new float[0]; var ob = new byte[0]; string why = "stdin_closed";
    while (open) {
      if (eventMode) ev.WaitOne(100); else Thread.Sleep(5);
      for (;;) {
        uint next; if (cc.GetNextPacketSize(out next) != 0) { why = "device_lost"; open = false; break; } // the default speaker went away / changed: the agent starts a fresh run
        if (next == 0) break;
        IntPtr data; uint n, flags; ulong devPos, qpc;
        if (cc.GetBuffer(out data, out n, out flags, out devPos, out qpc) != 0) break;
        packets++; frames += n;
        if (ob.Length < n * 4) { ob = new byte[n * 4]; fl = new float[n * 2]; }
        if ((flags & 2) != 0) { silent++; Array.Clear(ob, 0, (int)n * 4); }
        else {
          Marshal.Copy(data, fl, 0, (int)n * 2);
          for (int i = 0; i < n * 2; i++) { float v = fl[i]; float a = Math.Abs(v); if (a > peak) peak = a; short x = (short)Math.Max(-32768, Math.Min(32767, (int)Math.Round(v * 32767))); ob[i * 2] = (byte)x; ob[i * 2 + 1] = (byte)(x >> 8); }
        }
        cc.ReleaseBuffer(n);
        try { outStream.Write(ob, 0, (int)n * 4); outStream.Flush(); outBytes += n * 4; } catch { why = "stdout_closed"; open = false; break; }
      }
      int sec = (int)(DateTime.UtcNow - t0).TotalSeconds;
      if (sec != lastSec) { lastSec = sec; Ev("{\"ev\":\"stats\",\"packets\":" + packets + ",\"frames\":" + frames + ",\"silent\":" + silent + ",\"peakDb\":" + (peak > 0 ? Math.Round(20 * Math.Log10(peak), 1).ToString(System.Globalization.CultureInfo.InvariantCulture) : "-999") + "}"); peak = 0; }
    }
    open = false;
    lb.Stop(); ka.Stop();
    Ev("{\"ev\":\"end\",\"why\":\"" + why + "\",\"frames\":" + frames + ",\"bytes\":" + outBytes + "}");
    return 0;
  }

  /// setdefault: the default capture endpoint for all three roles (VS_MIC_DEVICE = its id).
  static int SetDefault() {
    string id = Environment.GetEnvironmentVariable("VS_MIC_DEVICE") ?? "";
    if (id == "") throw new Exception("VS_MIC_DEVICE names no endpoint");
    IMMDevice d; Ep.Check(Ep.En().GetDevice(id, out d), "GetDevice");
    var pc = (IPolicyConfig)new PolicyConfigClient();
    for (int r = 0; r < 3; r++) Ep.Check(pc.SetDefaultEndpoint(id, r), "SetDefaultEndpoint " + Roles[r]);
    Console.WriteLine("{\"ok\":true,\"endpoint\":" + Q(Ep.NameOf(d)) + ",\"id\":" + Q(id) + "}");
    return 0;
  }
}
}
